import math

def haversine(lat1, lon1, lat2, lon2, R=6371.0):
    p1, p2 = math.radians(lat1), math.radians(lat2)
    dphi = math.radians(lat2-lat1)
    dlmb = math.radians(lon2-lon1)
    a = math.sin(dphi/2)**2 + math.cos(p1)*math.cos(p2)*math.sin(dlmb/2)**2
    return 2*R*math.asin(math.sqrt(a))

# Candidate coordinate sets
accra_sets = {
    "Accra (5.6037, -0.1870)": (5.6037, -0.1870),
    "Accra (5.55, -0.20)": (5.55, -0.20),
    "Accra (5.6, -0.19)": (5.6, -0.19),
}
sd_sets = {
    "San Diego (32.7157, -117.1611)": (32.7157, -117.1611),
    "San Diego (32.72, -117.16)": (32.72, -117.16),
}

for an,(ala,alo) in accra_sets.items():
    for sn,(sla,slo) in sd_sets.items():
        d = haversine(ala,alo,sla,slo)
        print(f"{an} -> {sn}: {d:.1f} km  (rounded to 10: {round(d,-1):.0f})")
"}

